def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_tau_x_squared(x):
    if x == 1:
        return 1 # tau(1^2) = 1
    factors_x = prime_factorization(x)

    # tau(x^2) = product((2*a_i + 1))
    tau_x_squared = 1
    for exponent in factors_x.values():
        tau_x_squared *= (2 * exponent + 1)
    return tau_x_squared

def calculate_s_x(x):
    tau = calculate_tau_x_squared(x)
    # S(x) = (tau(x^2) - 1) / 2
    return (tau - 1) // 2

candidates = [1679, 1681, 1682, 1683, 1684, 1685]
results = {}
max_s = -1
best_x = None

for x in candidates:
    s_x = calculate_s_x(x)
    results[x] = s_x
    if s_x > max_s:
        max_s = s_x
        best_x = x

print("S(x) values:", results)
print("Maximum S(x) found:", max_s)
print("Corresponding x:", best_x)
